sys_script_include.script:
var FilterAvailableBases = Class.create();
FilterAvailableBases.prototype = {
    initialize: function() {},

    getAvailableBases: function() {
        var userID = gs.getUserID();  // Obtém o ID do usuário logado
        var availableBases = [];

        // 🔍 1️⃣ Verifica se o usuário já tem um registro de inscrição ativo (exceto rejeitados)
        var userEnrollment = new GlideRecord('x_1546361_bases_access_registration');
        userEnrollment.addQuery('requester_name', userID); // Usa o campo correto de referência ao usuário
        userEnrollment.addQuery('state', '!=', 7); // Confirme se "7" representa "Rejeitado"
        userEnrollment.query();

        var blockedBases = [];
        while (userEnrollment.next()) {
            blockedBases.push(userEnrollment.base.toString()); // Coleta as bases onde o usuário já está inscrito
        }

        // 🔍 2️⃣ Busca bases com vagas disponíveis
        var baseRecord = new GlideRecord('x_1546361_bases_bases');
        baseRecord.addQuery('maximum_capacity', '>', 0); // Somente bases com espaço disponível
        baseRecord.query();

        while (baseRecord.next()) {
            if (blockedBases.indexOf(baseRecord.sys_id.toString()) === -1) { 
                availableBases.push(baseRecord.sys_id.toString()); // Só adiciona se o usuário não estiver registrado
            }
        }

        if (availableBases.length > 0) {
            return 'sys_idIN' + availableBases.join(',');
        }

        return 'sys_idINNONE'; // Caso nenhuma base esteja disponível
    },

    type: 'FilterAvailableBases'
};
